use vstd::prelude::*;

verus! {

spec fn all_eq(v: Seq<f32>, a: f32) -> bool {
    forall|i: int| 0 <= i < v.len() ==> v[i] == a
}

fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (x_grid: Vec<Vec<f32>>, y_grid: Vec<Vec<f32>>)
    ensures
        x_grid.len() == y.len(),
        y_grid.len() == y.len(),
        forall|i: int| 0 <= i < y.len() as int ==> x_grid[i].len() == x.len(),
        forall|i: int| 0 <= i < y.len() as int ==> y_grid[i].len() == x.len(),
        // x_grid rows are copies of x
        forall|i: int| 0 <= i < y.len() as int ==> x_grid[i]@ == x@,
        // y_grid rows are filled with the corresponding y value
        forall|i: int| 0 <= i < y.len() as int ==> all_eq(y_grid[i]@, y@[i]),
{
    let rows = y.len();
    let cols = x.len();

    let mut x_grid: Vec<Vec<f32>> = Vec::with_capacity(rows);
    let mut y_grid: Vec<Vec<f32>> = Vec::with_capacity(rows);

    for &yv in y.iter()
        invariant
            x_grid.len() == y_grid.len(),
            x_grid.len() <= y.len(),
            // established rows so far satisfy the postconditions
            forall|i: int| 0 <= i < x_grid.len() as int ==> x_grid[i].len() == x.len(),
            forall|i: int| 0 <= i < y_grid.len() as int ==> y_grid[i].len() == x.len(),
            forall|i: int| 0 <= i < x_grid.len() as int ==> x_grid[i]@ == x@,
            forall|i: int| 0 <= i < y_grid.len() as int ==> all_eq(y_grid[i]@, y@[i]),
        decreases
            y.len() - x_grid.len(),
    {
        // Each row of x_grid is a copy of x
        x_grid.push(x.clone());

        // Each row of y_grid is filled with the corresponding y value
        y_grid.push(vec![yv; cols]);

        // Help the verifier connect the new y_grid row with y's prefix
        assert(x_grid.len() == y_grid.len());
        assert(x_grid.len() <= y.len());
        assert(forall|i: int| 0 <= i < x_grid.len() as int ==> x_grid[i]@ == x@);
        assert(forall|i: int| 0 <= i < y_grid.len() as int ==> all_eq(y_grid[i]@, y@[i]));
    }

    (x_grid, y_grid)
}

} // verus!

